export const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (c) => ({ k: 'e', v: c })
const num = (v) => ({ k: 'n', v })

export function parseAddress(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { col, row, key: letters + row }
}

export function colName(col) {
  return col > 26 ? String.fromCharCode(64 + Math.floor((col - 1) / 26), 65 + ((col - 1) % 26)) : String.fromCharCode(64 + col)
}

function tokenize(s) {
  const out = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^\d+(\.\d+)?/.exec(s.slice(i)))) { out.push({ t: 'num', v: m[0] }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { out.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    const two = s.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { out.push({ t: 'op', v: two }); i += 2; continue }
    if ('^*/+-=<>(),:'.includes(c)) { out.push({ t: 'op', v: c }); i++; continue }
    return null
  }
  return out
}

// Returns an AST or null when the grammar rejects the body.
export function parse(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('syntax') }
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const cmpOps = ['=', '<>', '<', '<=', '>', '>=']

  function expr() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && cmpOps.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return atom()
  }
  function atom() {
    if (p >= toks.length) fail()
    const tk = toks[p]
    if (tk.t === 'num') { p++; return { t: 'num', v: Number(tk.v) } }
    if (tk.t === 'op' && tk.v === '(') {
      p++
      const e = expr()
      if (!isOp(')')) fail()
      p++
      return { t: 'paren', e }
    }
    if (tk.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(expr())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      const up = tk.v.toUpperCase()
      if (up === 'TRUE') return { t: 'bool', v: true }
      if (up === 'FALSE') return { t: 'bool', v: false }
      if (isOp(':') && p + 1 < toks.length && toks[p + 1].t === 'word') {
        p++
        const b = toks[p++].v
        return { t: 'range', a: tk.v, b }
      }
      return { t: 'ref', a: tk.v }
    }
    fail()
  }
  try {
    const e = expr()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}

function rangeCells(a, b) {
  const x = parseAddress(a), y = parseAddress(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++) {
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: c, row: r, key: colName(c) + r })
  }
  return out
}

export function deps(ast) {
  const set = new Map()
  const add = (a) => { if (a) set.set(a.key, a) }
  const walk = (n) => {
    switch (n.t) {
      case 'ref': add(parseAddress(n.a)); break
      case 'range': for (const c of rangeCells(n.a, n.b) || []) add(c); break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(ast)
  return [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row).map((a) => a.key)
}

function toNum(v) {
  if (v.k === 'e') return v
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function cmpPoints(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 's') return cmpPoints(a.v, b.v)
  const x = Number(a.v), y = Number(b.v)
  return x < y ? -1 : x > y ? 1 : 0
}

// getCell(key) -> value
export function evaluate(ast, getCell) {
  const ref = (a) => {
    const ad = parseAddress(a)
    return ad ? getCell(ad.key) : err('#REF!')
  }
  function ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { k: 'b', v: n.v }
      case 'paren': return ev(n.e)
      case 'ref': return ref(n.a)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = toNum(ev(n.e))
        if (v.k === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': {
        const l = ev(n.l)
        if (l.k === 'e') return l
        const r = ev(n.r)
        if (r.k === 'e') return r
        if (cmpOps.has(n.op)) {
          const c = compare(l, r)
          switch (n.op) {
            case '=': return { k: 'b', v: c === 0 }
            case '<>': return { k: 'b', v: c !== 0 }
            case '<': return { k: 'b', v: c < 0 }
            case '<=': return { k: 'b', v: c <= 0 }
            case '>': return { k: 'b', v: c > 0 }
            default: return { k: 'b', v: c >= 0 }
          }
        }
        const a = toNum(l)
        if (a.k === 'e') return a
        const b = toNum(r)
        if (b.k === 'e') return b
        switch (n.op) {
          case '+': return finite(a.v + b.v)
          case '-': return finite(a.v - b.v)
          case '*': return finite(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
          default: return finite(Math.pow(a.v, b.v))
        }
      }
      case 'call': return call(n)
    }
  }
  function call(n) {
    const { name, args } = n
    const agg = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (agg.includes(name)) {
      if (args.length < 1) return err('#ERR!')
      const vals = []
      for (const a of args) {
        if (a.t === 'range') {
          const cells = rangeCells(a.a, a.b)
          if (!cells) vals.push(err('#REF!'))
          else for (const c of cells) vals.push(getCell(c.key))
        } else vals.push(ev(a))
      }
      const e = vals.find((v) => v.k === 'e')
      if (e) return e
      if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
      const ns = []
      for (const v of vals) {
        const x = toNum(v)
        if (x.k === 'e') return x
        ns.push(x.v)
      }
      if (name === 'SUM') return finite(ns.reduce((s, x) => s + x, 0))
      if (name === 'AVG') return finite(ns.reduce((s, x) => s + x, 0) / ns.length)
      return num(name === 'MIN' ? Math.min(...ns) : Math.max(...ns))
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const v = toNum(ev(args[0]))
      return v.k === 'e' ? v : num(Math.abs(v.v))
    }
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const c = ev(args[0])
      if (c.k === 'e') return c
      if (c.k === 's') return err('#VALUE!')
      const truth = c.k === 'b' ? c.v : c.v !== 0
      return ev(truth ? args[1] : args[2])
    }
    return err('#NAME?')
  }
  return ev(ast)
}
const cmpOps = new Set(['=', '<>', '<', '<=', '>', '>='])
"}

