{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */
import { readFileSync } from 'node:fs'
import { ERRORS, parse, parseAddress, evaluate, deps } from './formula.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

function die(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
  const word = m[1]
  const content = m[2]
  const ad = parseAddress(word)
  if (!ad) die(`line ${i + 1}: invalid cell address ${word}`)
  if (cells.has(ad.key)) die(`line ${i + 1}: cell ${ad.key} is declared twice`)
  cells.set(ad.key, { ...ad, content })
})

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)

for (const c of sorted) {
  const t = c.content
  if (t[0] === '=') {
    c.ast = parse(t.slice(1))
  } else if (t === '') c.lit = { k: 'n', v: 0 }
  else if (/^-?\d+(\.\d+)?$/.test(t)) c.lit = { k: 'n', v: Number(t) }
  else if (ERRORS.includes(t)) c.lit = { k: 'e', v: t }
  else c.lit = { k: 's', v: t }
}

const out = []
if (mode === 'deps') {
  for (const c of sorted) {
    const d = c.ast ? deps(c.ast) : []
    out.push(`${c.key}:${d.map((x) => ' ' + x).join('')}`)
  }
} else {
  const memo = new Map()
  const active = new Set()
  const get = (key) => {
    if (memo.has(key)) return memo.get(key)
    const c = cells.get(key)
    if (!c) return { k: 'n', v: 0 }
    if (c.lit) return c.lit
    if (active.has(key)) return { k: 'e', v: '#CYCLE!' }
    active.add(key)
    const v = c.ast ? evaluate(c.ast, get) : { k: 'e', v: '#ERR!' }
    active.delete(key)
    memo.set(key, v)
    return v
  }
  for (const c of sorted) {
    const v = get(c.key)
    let s
    if (v.k === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.k === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out.push(`${c.key}=${s}`)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

