for (const c of sorted) {
  const t = c.content
  if (t[0] === '=') {
    c.ast = parse(t.slice(1))
  } else if (t === '') c.lit = { k: 'n', v: 0 }
  else if (/^-?\d+(\.\d+)?$/.test(t)) c.lit = { k: 'n', v: Number(t) }
  else if (ERRORS.includes(t)) c.lit = { k: 'e', v: t }
  else c.lit = { k: 's', v: t }
}

const out = []
if (mode === 'deps') {
  for (const c of sorted) {
    const d = c.ast ? deps(c.ast) : []
    out.push(`${c.key}:${d.map((x) => ' ' + x).join('')}`)
  }
} else {
  const memo = new Map()
  const active = new Set()
  const get = (key) => {
    if (memo.has(key)) return memo.get(key)
    const c = cells.get(key)
    if (!c) return { k: 'n', v: 0 }
    if (c.lit) return c.lit
    if (active.has(key)) return { k: 'e', v: '#CYCLE!' }
    active.add(key)
    const v = c.ast ? evaluate(c.ast, get) : { k: 'e', v: '#ERR!' }
    active.delete(key)
    memo.set(key, v)
    return v
  }
  for (const c of sorted) {
    const v = get(c.key)
    let s
    if (v.k === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.k === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out.push(`${c.key}=${s}`)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
